arguments.command:
cd /workspace && python3 - <<'PY'
import sys,random,time
sys.path.insert(0,'/workspace/submission');sys.path.insert(0,'/workspace/tmp')
from compiler import compile_plan, find_deficient_cut
from compiler_proto import validate_plan
random.seed(999)
t0=time.time(); prep=den=0
for it in range(5000):
 n=random.randint(2,11)
 np=random.randint(2,min(7,n))
 C=sorted(random.sample(range(n),np))
 roots={v:random.choice([0,0,1,2,3,5]) for v in C}
 if sum(roots.values())==0:roots[C[0]]=1
 links=[]
 for u in range(n):
  for v in range(u+1,n):
   if random.random()<0.4:links.append((u,v))
 env={i:random.choice([0,0,1,1,2,3]) for i in range(len(links))}
 p=random.choice([1,2,3])
 try:
  cut=find_deficient_cut(n,links,C,roots,p,env)
  out,payload=compile_plan(n,links,C,roots,p,env)
  if cut is not None:
   assert out=='denied',(out,payload)
   den+=1
  else:
   assert out=='prepared'
   validate_plan(payload,n,links,C,roots,p,env)
   prep+=1
 except Exception as e:
  print('FAIL it',it,'n',n,'C',C,'roots',roots,'links',links,'env',env,'p',p,'cut',cut,repr(e));raise
 if it%1000==0:print('it',it,'prep',prep,'den',den,'time',round(time.time()-t0,2),flush=True)
print('DONE prep',prep,'den',den,'time',time.time()-t0)
PY
